def minCostEqualize(nums, cost):
    pairs = sorted(zip(nums, cost))
    total = sum(cost)
    acc = 0
    target = pairs[-1][0]
    for v, w in pairs:
        acc += w
        if acc * 2 >= total:
            target = v
            break
    return sum(w * abs(v - target) for v, w in pairs)
